/* известные дефекты: типы, для которых раскладка ещё не сходится с эталоном.
 * Их нельзя молча пропускать — тест обязан оставаться красным, пока
 * деквантизация не починена, иначе снова придётся ловить это на выходе
 * модели по косвенным признакам. */
static int check_type(const char *name, unsigned type,
                      const unsigned char (*blocks)[], int block_size,
                      const float *expect, int known_broken)
{
    float got[512];
    int   bad = 0;
    gguf_tensor t;
    memset(&t, 0, sizeof t);
    t.type = type;
    t.n_dims = 2;
    t.dims[0] = 512;      /* два блока по 256 */
    t.dims[1] = 1;
    t.data = (const unsigned char *)blocks;
    t.nbytes = (size_t)block_size * 2;

    if (gguf_dequant(&t, got, 0, 512) != 0) {
        printf("  %-6s gguf_dequant вернул ошибку\n", name);
        return 1;
    }

    for (int p = 0; p < 512; p++) {
        int   b   = p / 256, k = p % 256;
        float want = expect[b * 64 + k];   /* эталон записан на первые 64 */
        if (k >= 64) continue;
        if (!(fabsf(got[p] - want) <= 1e-6f * (fabsf(want) + 1e-6f))) {
            if (bad < 4)
                printf("  %-6s вес %d блока %d: получено %.9g, ожидалось %.9g\n",
                       name, k, b, (double)got[p], (double)want);
            bad++;
        }
    }
    if (!bad) {
        printf("  %-6s совпадает с эталоном\n", name);
        return 0;
    }
    printf("  %-6s расходится на %d из 128 проверенных весов%s\n", name, bad,
           known_broken ? "  <- ИЗВЕСТНЫЙ ДЕФЕКТ, не починен" : "");
    return 1;
}

int main(void)
{
    printf("деквантизация K-квантов против эталона ggml\n\n");
    int bad = 0;
    bad += check_type("Q2_K", 10, blk_Q2_K,  84, &exp_Q2_K[0][0],  0);
    bad += check_type("Q4_K", 12, blk_Q4_K, 144, &exp_Q4_K[0][0],  0);
    bad += check_type("Q6_K", 14, blk_Q6_K, 210, &exp_Q6_K[0][0],  0);
    bad += check_type("Q3_K", 11, blk_Q3_K, 110, &exp_Q3_K[0][0],  0);
    printf("\n%s\n", bad ? "есть расхождения с эталоном" : "все типы совпали с эталоном");
    return bad ? 1 : 0;
}
